{
  "a_sentences": [
    {
      "a_text": "La juridiction cantonale a retenu que la personne assurée fondait sa demande d'indemnité sur la résiliation orale intervenue lors de la séance de conciliation du 23 février 2024.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Pour réclamer une indemnité pour résiliation abusive, la personne assurée doit former opposition par écrit auprès de l'employeur au plus tard à la fin du délai de congé.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "Elle doit alléguer et prouver les faits permettant de conclure à une opposition valable.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "La juridiction cantonale a estimé qu'un requête de conciliation tendant à la constatation de la résiliation abusive satisfaisait aux exigences de l'opposition au sens de l'art. 336b al. 1 CO, mais que l'opposition ne serait formée qu'à la notification de cette requête à l'employeur.",
      "b_propositions": ["P4", "P5"]
    },
    {
      "a_text": "Le délai pour former opposition contre la résiliation est un délai de péremption.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "La partie demanderesse ne peut pas attendre que la partie défenderesse invoque la péremption pour alléguer et prouver qu'elle a formé opposition en temps utile.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le Tribunal fédéral retient que la personne assurée échoue à démontrer qu'elle a allégué et prouvé les faits permettant de conclure à une opposition formée dans le délai.",
      "b_propositions": ["P8"]
    }
  ]
}
